# Apply dossiers and population evidence.
for c in arr:
    if c['id'] in dossiers:
        d=dossiers[c['id']]
        c['history']=d['history']['en']
        c['description']['ku']=d['history']['ku']
        c['description']['en']=d['history']['en']
        c['description']['fa']=d['history']['fa']
        for key in ['geography','languages','culture','crafts','economy']:
            c[key]=d[key]
        c['heritage']=d['heritage']
        c['attraction']=d['heritage']['en']
    if c['id'] in city_pops:
        val,yr,srcname,url=city_pops[c['id']]
        c['population']=f'{val:,} ({yr} census)'
        c['populationYear']=yr
        c['populationSource']=srcname
        c['populationStatus']='city_level_verified_secondary_transcription'
        c['populationNote']='City/locality population for 2024; secondary transcription of the 2024 Iraq census. Governorate/district totals are kept separately.'
        # preserve sources and add city population source
        c.setdefault('sources',[])
        c['sources']=[s for s in c['sources'] if s.get('label')!='City-level population source']
        c['sources'].append({'label':'City-level population source — 2024 Iraq census transcription','url':url})
        c['evidence']['population']={'status':'documented-secondary','label':'Population'}
    else:
        c['populationStatus']=c.get('populationStatus','city_level_not_verified')
    # evidence field statuses
    for key in ['history','geography','languages','culture','crafts','economy','heritage']:
        if c.get(key): c['evidence'][key]={'status':'documented','label':key.title()}
    c['researchReviewed']='2026-09-07'
    c['evidenceStandard']='v4.1-city-dossier'
    c['recordIntegrity']=c.get('recordIntegrity','')
    if c['id'] in dossiers: c['evidenceScore']=min(11, max(c.get('evidenceScore',0), 9))

open(base+'/cities-data.js','w',encoding='utf8').write('window.KURD_CITIES='+json.dumps(arr,ensure_ascii=False,separators=(',',':'))+';\n')

